import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useSocket } from '../../context/SocketContext'; // Adjust the import path as needed
import styles from './NewGamePage.module.css';

const NewGamePage = () => {
    const [showModal, setShowModal] = useState(false);
    const [maxPlayers, setMaxPlayers] = useState(4);
    const [botCount, setBotCount] = useState(0);
    const [error, setError] = useState('');
    const socket = useSocket();
    const navigate = useNavigate();

    useEffect(() => {
        if (socket) {
            socket.on('gameCreated', ({ gameId }) => {
                console.log('Game created with ID:', gameId);
                localStorage.setItem('currentGame', JSON.stringify({ gameId, playerId: socket.id }));
                navigate(`/game/${gameId}`);
            });

            socket.on('gameError', ({ message }) => {
                setError(message);
            });

            // Check for existing game
            const savedGame = JSON.parse(localStorage.getItem('currentGame'));
            if (savedGame) {
                socket.emit('reconnectToGame', savedGame);
            }

            socket.on('gameReconnected', ({ gameId, gameState }) => {
                console.log('Reconnected to game:', gameId);
                navigate(`/game/${gameId}`);
            });

            socket.on('reconnectError', ({ message }) => {
                console.log('Reconnection failed:', message);
                localStorage.removeItem('currentGame');
            });

            return () => {
                socket.off('gameCreated');
                socket.off('gameError');
                socket.off('gameReconnected');
                socket.off('reconnectError');
            };
        }
    }, [socket, navigate]);

    const handleCreateGame = () => {
        setShowModal(true);
        setError('');
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (maxPlayers - botCount < 1) {
            setError('At least one human player is required.');
            return;
        }
        if (botCount + (maxPlayers - botCount) > 4) {
            setError('Total number of players (bots + humans) must not exceed 4.');
            return;
        }

        // Emit socket event to create a new game
        if (socket) {
            socket.emit('createGame', {
                maxPlayers: maxPlayers,
                botCount: botCount,
                allowedPlayers: maxPlayers - 1 // Subtracting 1 to account for the creator
            });
        }

        setShowModal(false);
    };

    return (
        <div className={styles.createGamePage}>
            <h2>Create New Game</h2>
            <button onClick={handleCreateGame}>Create Game</button>

            {showModal && (
                <div className={styles.modal}>
                    <div className={styles.modalContent}>
                        <h3>Game Settings</h3>
                        <form onSubmit={handleSubmit}>
                            <div>
                                <label htmlFor="maxPlayers">Max Players:</label>
                                <select
                                    id="maxPlayers"
                                    value={maxPlayers}
                                    onChange={(e) => {
                                        setMaxPlayers(Number(e.target.value));
                                        setError('');
                                    }}
                                >
                                    <option value="2">2</option>
                                    <option value="3">3</option>
                                    <option value="4">4</option>
                                </select>
                            </div>
                            <div>
                                <label htmlFor="botCount">Number of Bots:</label>
                                <input
                                    type="number"
                                    id="botCount"
                                    value={botCount}
                                    onChange={(e) => {
                                        setBotCount(Number(e.target.value));
                                        setError('');
                                    }}
                                    min="0"
                                    max={maxPlayers - 1}
                                />
                            </div>
                            {error && <div className={styles.error}>{error}</div>}
                            <div className={styles.modalActions}>
                                <button type="submit">Create</button>
                                <button type="button" onClick={() => setShowModal(false)}>Cancel</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default NewGamePage;
